def _standardize(self, X):

    if self.means is None or self.stds is None:
        raise RuntimeError("Fit model first")

    return (X - self.means) / self.stds

def transform(self, data=None):

    if self.C is None:
        raise RuntimeError('Fit the data model first.')
    if data is None:
        return np.dot(self.data, self.C)
    return np.dot(data, self.C)

def _calc_var(self):

    if self.data is None:
        raise RuntimeError('Fit the data model first.')

    data = self.data.T

    # variance calc
    var = np.nanvar(data, axis=1)
    total_var = var.sum()
    self.var_exp = self.eig_vals.cumsum() / total_var

def fill_missing(x):

    # ppca if missing data
    m = PPCA()
    m.fit(data=np.vstack(x))
    x_pca = m.transform()

    # if the whole row is missing, return nans
    all_missing = [idx for idx, a in enumerate(np.vstack(x)) if all([type(b)==np.nan for b in a])]
    if len(all_missing)>0:
        for i in all_missing:
            x_pca[i, :] = np.nan

    # get the original lists back
    if len(x)>1:
        x_split = np.cumsum([i.shape[0] for i in x][:-1])
        return list(np.split(x_pca, x_split, axis=0))
    else:
        return [x_pca]

def group_by_category(vals):
